def transform(grid):
    from collections import Counter
    g = np.array(grid)
    bg = background(g)
    MK = 5
    work = g.copy(); work[g == MK] = bg
    emit(work.copy(), "Remove the two colour-5 window markers; remember their bounding box as the window.")

    def runs(v):
        out = []; s = None
        for i, b in enumerate(v):
            if b and s is None: s = i
            if not b and s is not None: out.append((s, i - 1)); s = None
        if s is not None: out.append((s, len(v) - 1))
        return out

    occ = work != bg
    T = len(runs(occ.any(0))) > len(runs(occ.any(1)))
    A = work.T.copy() if T else work.copy()
    Mk = (g == MK).T if T else (g == MK)
    pts = np.argwhere(Mk)
    wy0, wx0 = pts.min(0); wy1, wx1 = pts.max(0)
    grp = runs((A != bg).any(1))
    F = wy0 < grp[0][0]
    H, W = A.shape
    if F:
        A = A[::-1].copy()
        wy0, wy1 = H - 1 - wy1, H - 1 - wy0
        grp = runs((A != bg).any(1))
    P = 15
    WW = W + 2 * P

    def line_of(r):
        arr = np.full(WW, bg); arr[P:P + W] = A[r]; return arr

    groups = [{'start': s, 'lines': [line_of(r) for r in range(s, e + 1)]} for s, e in grp]

    cnt = Counter()
    for a, b in zip(groups, groups[1:]):
        for la, lb in zip(a['lines'], b['lines']):
            m = (la != bg) & (lb != bg)
            for u, v in zip(la[m], lb[m]): cnt[(int(u), int(v))] += 1
    step = {}
    for (u, v), c in cnt.most_common():
        if u not in step: step[u] = v

    def ap(line, use):
        if not use: return line.copy()
        return np.array([step.get(int(v), int(v)) if v != bg else bg for v in line])

    def extent(line):
        nz = np.nonzero(line != bg)[0]
        return None if len(nz) == 0 else (int(nz.min()), int(nz.max()))

    def best_period(s):
        n = len(s); best = None
        for p in range(1, n):
            f = {}; inv = {}; r = 0
            for i in range(n - 1, p - 1, -1):
                a, b = s[i - p], s[i]
                if (a == bg) != (b == bg): break
                if f.get(a, b) != b or inv.get(b, a) != a: break
                f[a] = b; inv[b] = a; r += 1
            if r < p: continue
            sc = r - p
            if best is None or sc > best[0]: best = (sc, p, f)
        return best

    def extend_right(s, k):
        s = list(s)
        if k <= 0: return s[:len(s) + k] if k < 0 else s
        bp = best_period(s)
        p, f = (1, {}) if bp is None else (bp[1], bp[2])
        for _ in range(k):
            a = s[-p]; s.append(f.get(a, a))
        return s

    def pred(hist):
        if len(hist) == 1: return hist[-1]
        if len(hist) == 2: d = [hist[-1][i] - hist[-2][i] for i in range(len(hist[-1]))]
        else: d = [hist[-2][i] - hist[-3][i] for i in range(len(hist[-1]))]
        return tuple(hist[-1][i] + d[i] for i in range(len(d)))

    def expand(line, s, c):
        if s == 0: return line.copy()
        out = np.full_like(line, bg)
        for i in np.nonzero(line != bg)[0]:
            j = i - s if i < c else (i + s if i > c else i)
            if 0 <= j < len(out): out[j] = line[i]
        return out

    def center(lines):
        nz = [i for ln in lines for i in np.nonzero(ln != bg)[0]]
        return (min(nz) + max(nz)) / 2 if nz else WW / 2

    rule = (1, 0, False)
    if len(groups) >= 2 and len(groups[-1]['lines']) > len(groups[-2]['lines']):
        Lg = groups[-1]['lines']; c = center(Lg); n0 = len(groups[-2]['lines'])
        done = False
        for q in range(1, n0 + 1):
            for s in range(0, 4):
                for use in (False, True):
                    if all(l - q >= 0 and np.array_equal(Lg[l], expand(ap(Lg[l - q], use), s, c))
                           for l in range(n0, len(Lg))):
                        rule = (q, s, use); done = True; break
                if done: break
            if done: break

    def to_orig(canvas_full):
        sub = canvas_full[:H, P:P + W]
        if F: sub = sub[::-1]
        if T: sub = sub.T
        return sub.copy()

    new_groups = []
    while True:
        lens = [len(gr['lines']) for gr in groups]
        nl = max(1, pred([(x,) for x in lens])[0])
        gap = groups[-1]['start'] - (groups[-2]['start'] + lens[-2]) if len(groups) >= 2 else 1
        start = groups[-1]['start'] + lens[-1] + gap
        prev = groups[-1]['lines']
        new = []
        for l in range(nl):
            if l < len(prev):
                src = ap(prev[l], True)
                hist = [extent(gr['lines'][l]) for gr in groups
                        if l < len(gr['lines']) and extent(gr['lines'][l]) is not None]
                ex = extent(src)
                if not hist or ex is None:
                    new.append(np.full(WW, bg)); continue
                lo, hi = ex; nlo, nhi = pred(hist)
                seg = list(src[lo:hi + 1])
                seg = extend_right(seg, nhi - hi)
                seg = extend_right(seg[::-1], lo - nlo)[::-1]
                out = np.full(WW, bg)
                for k, v in enumerate(seg):
                    j = nlo + k
                    if 0 <= j < WW: out[j] = v
                new.append(out)
            else:
                q, s, use = rule
                c = center(new[:len(prev)])
                new.append(expand(ap(new[l - q], use), s, c))
        gr = {'start': start, 'lines': new}
        groups.append(gr); new_groups.append(gr)
        BH = max(H, start + nl)
        canvas = np.full((BH, WW), bg)
        canvas[:H, P:P + W] = A
        for ng in new_groups:
            for k, ln in enumerate(ng['lines']):
                canvas[ng['start'] + k] = ln
        emit(to_orig(canvas), f"Extend the sequence: draw the next group ({nl} lines) continuing sizes, colours and patterns.")
        if start + nl - 1 >= wy1 or len(new_groups) > 10:
            break

    out = canvas[wy0:wy1 + 1, P + wx0:P + wx1 + 1].copy()
    if F: out = out[::-1]
    if T: out = out.T
    out = np.array(out)
    emit(out, "Crop the window marked by the colour-5 corners.")
    return out
